{
  "appearance_facts": [
    {
      "location": "Page title at top center, y≈120",
      "fact": "Large bold text reads 'City Emissions Reduction by Program'. A y-axis label at top-left, y≈270, reads 'Reported reduction share (%)'."
    },
    {
      "location": "Plot area, x from ≈240 to ≈2160, y from ≈300 to ≈1530",
      "fact": "Five vertical bars of equal width sit on a common baseline at y≈1530, separated by white gaps. Bar heights vary, with the second bar clearly the tallest."
    },
    {
      "location": "Bar 1, x≈310-525, top y≈825",
      "fact": "Medium green bar; its top aligns just above the 40 gridline. A bold black data label '41.2%' sits centered above it at y≈775."
    },
    {
      "location": "Bar 2, x≈700-915, top y≈335",
      "fact": "Light blue (sky blue) bar, the tallest in the chart, extending above the 65 gridline near the 70 tick. A bold black data label '29.8%' sits centered above it at y≈290."
    },
    {
      "location": "Bar 3, x≈1090-1305, top y≈620",
      "fact": "Periwinkle/light purple bar, top just above the 50 gridline. A bold black data label '18.5%' sits centered above it at y≈565."
    },
    {
      "location": "Bar 4, x≈1480-1695, top y≈1135",
      "fact": "Dark green bar, top just above the 20 gridline. A bold black data label '7.2%' sits centered above it at y≈1080."
    },
    {
      "location": "Bar 5, x≈1870-2085, top y≈920",
      "fact": "Brown bar, top just above the 35 gridline. A bold black data label '3.3%' sits centered above it at y≈865."
    },
    {
      "location": "X-axis category labels, y≈1590-1640",
      "fact": "Two-line labels under each bar read left-to-right: 'Building retrofits', 'Transit electrification', 'Industrial efficiency', 'Tree canopy', 'Methane capture'."
    }
  ],
  "printed_facts": [
    {
      "location": "Y-axis, x≈150, ticks y≈300 to 1530",
      "fact": "Numeric ticks in increments of 5 from 0 (bottom) to 70 (top): 0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55, 60, 65, 70. Axis title 'Reported reduction share (%)'."
    },
    {
      "location": "Bar 1 data label",
      "fact": "Series 'Building retrofits' (medium green) annotated '41.2%'; bar top visually at ≈40 on the y-axis."
    },
    {
      "location": "Bar 2 data label",
      "fact": "Series 'Transit electrification' (light blue) annotated '29.8%'; bar top visually at ≈68 on the y-axis (tallest bar)."
    },
    {
      "location": "Bar 3 data label",
      "fact": "Series 'Industrial efficiency' (periwinkle) annotated '18.5%'; bar top visually at ≈52 on the y-axis."
    },
    {
      "location": "Bar 4 data label",
      "fact": "Series 'Tree canopy' (dark green) annotated '7.2%'; bar top visually at ≈22 on the y-axis."
    },
    {
      "location": "Bar 5 data label",
      "fact": "Series 'Methane capture' (brown) annotated '3.3%'; bar top visually at ≈35 on the y-axis."
    },
    {
      "location": "Chart-wide",
      "fact": "The data labels (41.2, 29.8, 18.5, 7.2, 3.3) do not sum to 100 and do not match the bar heights in a consistent order; e.g., the tallest bar (Transit electrification) carries the second-largest label, and the shortest bar (Methane capture) carries a label (3.3%) smaller than Tree canopy's (7.2%) yet a taller bar."
    }
  ],
  "public_definitions": [
    "Routing basis: 'Largest city emissions-reduction contribution program'.",
    "Escalation queue: 'Accelerated program review'.",
    "Option: 'Route Building retrofits to accelerated program review'.",
    "Option: 'Route Transit electrification to accelerated program review'.",
    "Option: 'Keep Industrial efficiency in routine program monitoring'."
  ],
  "uncertain": [
    "The printed percentage labels and the bar heights disagree in ordering, so it is ambiguous whether 'largest contribution' should be read from the bar height (Transit electrification, tallest) or from the numeric label (Building retrofits, 41.2%).",
    "The y-axis is titled 'Reported reduction share (%)' but the bars and labels are not mutually consistent, so the intended scale for the target comparison is not fully clear."
  ]
}
